#!/usr/bin/env node
'use strict';

/**
 * Regenerates the TypeScript copy of the casting worker's result JSON Schema. The canonical file is
 * casting-worker/result.schema.json (the backend Docker build context cannot reach it). Never hand-edit the generated file; a
 * spec fails when it drifts.
 * Run from backend/:  npm run casting:sync-contract
 */

const fs = require('fs');
const path = require('path');

const source = path.resolve(__dirname, '../../casting-worker/result.schema.json');
const out = path.resolve(__dirname, '../src/modules/sand-casting/casting-result-schema.generated.ts');

function render(file = source) {
  return [
    '// GENERATED by scripts/sync-casting-contract.js from casting-worker/result.schema.json. Do not edit.',
    `export const CASTING_RESULT_SCHEMA = ${JSON.stringify(JSON.parse(fs.readFileSync(file, 'utf8')), null, 2)} as const;`,
    '',
  ].join('\n');
}

if (require.main === module) {
  fs.writeFileSync(out, render(process.argv[2] ? path.resolve(process.argv[2]) : source));
  console.log(`wrote ${path.relative(process.cwd(), out)}`);
}

module.exports = { render, out, source };
